              ))}
            </div>
            
            <div className="p-4 mt-6 rounded-lg bg-blue-50">
              <h5 className="mb-2 font-semibold">Action Items</h5>
              <p className="text-sm text-gray-600">
                Based on feedback, prioritize improving transportation and washroom facilities in tourist areas.
              </p>
            </div>
          </div>
        </div>
      </div>
    );
  }, []);

  return (
    <div className="min-h-screen bg-gray-50">
      <style>
        {`
          .leaflet-container {
            height: 100%;
            width: 100%;
            z-index: 1;
            border-radius: 0.5rem;
          }
          .custom-marker {
            transition: transform 0.2s;
          }
          .custom-marker:hover {
            transform: scale(1.2);
          }
          @keyframes bounce-slow {
            0%, 100% { transform: translateY(0); }
            50% { transform: translateY(-10px); }
          }
          .animate-bounce-slow {
            animation: bounce-slow 2s infinite;
          }
        `}
      </style>
      
      {/* Header */}
      <header className="sticky top-0 z-40 bg-white shadow-sm">
        <div className="flex flex-col items-start justify-between px-6 py-4 md:flex-row md:items-center">
          <div>
            <h1 className="flex items-center text-2xl font-bold text-gray-800">
              <span className="p-2 mr-3 text-white rounded-lg bg-gradient-to-r from-blue-600 to-purple-600">
                📊
              </span>
              Jharkhand Tourism Analytics
            </h1>
            <p className="mt-1 text-gray-600">
              {new Date().toLocaleDateString('en-IN', { 
                weekday: 'long', 
                year: 'numeric', 
                month: 'long', 
                day: 'numeric' 
              })}
            </p>
          </div>
          
          <div className="flex flex-wrap gap-2 mt-4 md:mt-0">
            <button
              onClick={() => setShowFilters(!showFilters)}
              className="flex items-center px-4 py-2 text-gray-700 transition-colors bg-white border border-gray-300 rounded-lg hover:bg-gray-50"
            >
              <span className="mr-2">🔍</span>
              Filters
              {showFilters && <span className="ml-2 text-blue-600">▼</span>}
            </button>
            
            <select
              value={timeRange}
              onChange={(e) => setTimeRange(e.target.value)}
              className="px-4 py-2 text-gray-700 bg-white border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              aria-label="Select time range"
            >
              <option value="weekly">Weekly</option>
              <option value="monthly">Monthly</option>
              <option value="quarterly">Quarterly</option>
              <option value="yearly">Yearly</option>
            </select>
            
            <button
              onClick={() => setMode(mode === "live" ? "demo" : "live")}
              className={`px-4 py-2 rounded-lg flex items-center transition-all ${
                mode === "live" 
                  ? "bg-gradient-to-r from-blue-600 to-blue-800 text-white hover:from-blue-700 hover:to-blue-900" 
                  : "bg-gradient-to-r from-gray-600 to-gray-800 text-white hover:from-gray-700 hover:to-gray-900"
              }`}
              aria-label={`Switch to ${mode === "live" ? "demo" : "live"} mode`}
            >
              <span className="mr-2 animate-pulse">{mode === "live" ? "🔴" : "⚪"}</span>
              {mode === "live" ? "Live View" : "Demo Mode"}
            </button>
          </div>
        </div>

        {/* Filters Panel */}
        {showFilters && (
          <div className="px-6 py-4 border-t border-gray-200 bg-gray-50">
            <div className="flex flex-wrap gap-4">
              <div className="flex-1 min-w-[200px]">
                <label className="block mb-1 text-sm font-medium text-gray-700">District</label>
                <select
                  value={selectedDistrict}
                  onChange={(e) => setSelectedDistrict(e.target.value)}
                  className="w-full px-3 py-2 text-sm text-gray-700 bg-white border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                >
                  <option value="All Districts">All Districts</option>
                  {DEMO_DATA.visitorsByDistrict.map((district, index) => (
                    <option key={index} value={district.district}>{district.district}</option>
                  ))}
                </select>
              </div>
              
              <div className="flex-1 min-w-[200px]">
                <label className="block mb-1 text-sm font-medium text-gray-700">Category</label>
                <select 
                  value={selectedCategory}
                  onChange={(e) => setSelectedCategory(e.target.value)}
                  className="w-full px-3 py-2 text-sm text-gray-700 bg-white border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                >
                  <option value="all">All Categories</option>
                  <option value="adventure">Adventure</option>
                  <option value="cultural">Cultural</option>
                  <option value="pilgrimage">Pilgrimage</option>
                  <option value="wildlife">Wildlife</option>
                </select>
              </div>
              
              <div className="flex-1 min-w-[200px]">
                <label className="block mb-1 text-sm font-medium text-gray-700">Date Range</label>
                <select 
                  value={dateRange}
                  onChange={(e) => setDateRange(e.target.value)}
                  className="w-full px-3 py-2 text-sm text-gray-700 bg-white border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                >
                  <option value="7">Last 7 days</option>
                  <option value="30">Last 30 days</option>
                  <option value="90">Last 90 days</option>
                  <option value="365">Last year</option>
                </select>
              </div>
              
              <div className="flex items-end">
                <button className="px-6 py-2 text-sm text-white transition-colors bg-blue-600 rounded-lg hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2">
                  Apply Filters
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Navigation Tabs */}
        <div className="px-6 overflow-x-auto border-t border-gray-200">
          <nav className="flex space-x-8">
            {[
              { id: "overview", label: "Overview", icon: "📊" },
              { id: "visitors", label: "Visitors", icon: "👥" },
              { id: "revenue", label: "Revenue", icon: "💰" },
              { id: "demographics", label: "Demographics", icon: "📈" },
              { id: "geospatial", label: "Map View", icon: "🗺️" },
              { id: "realtime", label: "Live", icon: "⚡" },
              { id: "predictive", label: "Predictive", icon: "🔮" },
              { id: "feedback", label: "Feedback", icon: "💬" }
            ].map(tab => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`py-4 px-1 font-medium text-sm border-b-2 whitespace-nowrap transition-colors ${
                  activeTab === tab.id 
                    ? "border-blue-500 text-blue-600" 
                    : "border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300"
                }`}
                aria-label={tab.label}
                aria-current={activeTab === tab.id ? "page" : undefined}
              >
                <span className="mr-2">{tab.icon}</span>
                {tab.label}
              </button>
            ))}
          </nav>
        </div>
      </header>

      {/* Main Content */}
      <main className="p-6">
        {isLoading ? (
          <div className="flex items-center justify-center h-96">
            <div className="text-center">
              <div className="w-16 h-16 mx-auto mb-4 border-4 border-blue-500 rounded-full border-t-transparent animate-spin"></div>
              <p className="text-gray-600">Loading dashboard data...</p>
              <p className="mt-2 text-sm text-gray-500">This may take a few moments</p>
            </div>
          </div>
        ) : mode === "live" && !embedFailed ? (
          <div 
            ref={reportRef} 
            className="report-container h-[70vh] border rounded-lg shadow bg-white"
            role="region"
            aria-label="Power BI Report"
          />
        ) : (
          <div className="space-y-6">
            {/* Overview Tab */}
            {activeTab === "overview" && (
              <div className="space-y-6">
                {/* Key Metrics */}
                <div className="grid grid-cols-1 gap-6 md:grid-cols-2 lg:grid-cols-4">
                  <MetricCard
                    icon="👥"
                    title="Total Visitors"
                    value="49,500"
                    change={12.5}
                    color="blue"
                  />
                  <MetricCard
                    icon="💰"
                    title="Total Revenue"
                    value="$232M"
                    change={8.2}
                    color="green"
                  />
                  <MetricCard
                    icon="📅"
                    title="Avg. Stay"
                    value="3.2 days"
                    change={-0.3}
                    color="purple"
                  />
                  <MetricCard
                    icon="⭐"
                    title="Satisfaction"
                    value="94%"
                    change={2}
                    color="orange"
                  />
                </div>

                {/* Charts */}
                <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
                  <div className="p-6 bg-white border border-gray-100 rounded-lg shadow">
                    <h3 className="flex items-center mb-4 text-lg font-bold">
                      <span className="mr-2">📈</span>
                      Visitors by District
                    </h3>
                    {renderVisitorsBarChart()}
                  </div>
                  
                  <div className="p-6 bg-white border border-gray-100 rounded-lg shadow">
                    <h3 className="flex items-center mb-4 text-lg font-bold">
                      <span className="mr-2">💹</span>
                      Revenue Trends ({timeRange})
                    </h3>
                    {renderRevenueChart()}
                  </div>
                </div>

                {/* Category Performance */}
                <div className="p-6 bg-white border border-gray-100 rounded-lg shadow">
                  <h3 className="flex items-center mb-4 text-lg font-bold">
                    <span className="mr-2">🏆</span>
                    Category Performance
                  </h3>
                  {renderCategoryPerformance()}
                </div>
              </div>
            )}

            {/* Visitors Tab */}
            {activeTab === "visitors" && (
              <div className="space-y-6">
                <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
                  <div className="p-6 bg-white border border-gray-100 rounded-lg shadow">
                    <h3 className="mb-4 text-lg font-bold">Visitors by District</h3>
                    {renderVisitorsBarChart()}
                  </div>
                  
                  <div className="p-6 bg-white border border-gray-100 rounded-lg shadow">
                    <h3 className="mb-4 text-lg font-bold">Monthly Visitor Trends</h3>
                    {renderVisitorTrends()}
                  </div>
                </div>
                
                <div className="grid grid-cols-1 gap-6 lg:grid-cols-3">
                  <div className="p-6 bg-white border border-gray-100 rounded-lg shadow">
                    <h4 className="mb-2 font-semibold">Peak Season</h4>
                    <p className="text-2xl font-bold text-blue-600">December</p>
                    <p className="text-sm text-gray-600">18,200 visitors</p>
                  </div>
                  <div className="p-6 bg-white border border-gray-100 rounded-lg shadow">
                    <h4 className="mb-2 font-semibold">Average Daily</h4>
                    <p className="text-2xl font-bold text-green-600">1,650</p>
                    <p className="text-sm text-gray-600">visitors per day</p>
                  </div>
                  <div className="p-6 bg-white border border-gray-100 rounded-lg shadow">
                    <h4 className="mb-2 font-semibold">Growth Rate</h4>
                    <p className="text-2xl font-bold text-purple-600">+12.5%</p>
                    <p className="text-sm text-gray-600">year over year</p>
                  </div>
                </div>
              </div>
            )}

            {/* Revenue Tab */}
            {activeTab === "revenue" && (
              <div className="space-y-6">
                <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
                  <div className="p-6 bg-white border border-gray-100 rounded-lg shadow">
                    <h3 className="mb-4 text-lg font-bold">Monthly Revenue</h3>
                    {renderRevenueChart()}
                  </div>
                  
                  <div className="p-6 bg-white border border-gray-100 rounded-lg shadow">
                    <h3 className="mb-4 text-lg font-bold">Revenue by Category</h3>
                    <div className="space-y-4">
                      {Object.entries(DEMO_DATA.revenueTrends.categories).map(([key, values]) => {
                        const total = values.reduce((a, b) => a + b, 0);
                        return (
                          <div key={key} className="flex items-center">
                            <span className="w-24 text-sm capitalize">{key}</span>
                            <div className="flex-1 h-4 bg-gray-200 rounded-full">
                              <div 
                                className="h-4 bg-green-500 rounded-full"
                                style={{ width: `${(total / 300) * 100}%` }}
                              ></div>
                            </div>
                            <span className="w-16 text-sm text-right">${total}M</span>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* Demographics Tab */}
            {activeTab === "demographics" && (
              <div className="p-6 bg-white border border-gray-100 rounded-lg shadow">
                <h3 className="mb-6 text-lg font-bold">Visitor Demographics</h3>
                {renderDemographicCharts()}
              </div>
            )}

            {/* Geospatial Tab */}
            {activeTab === "geospatial" && (
              <div className="p-6 bg-white border border-gray-100 rounded-lg shadow">
                <h3 className="flex items-center mb-4 text-lg font-bold">
                  <span className="mr-2">🗺️</span>
                  Visitor Geographic Distribution
                </h3>
                
                {/* Legend */}
                <div className="flex flex-wrap gap-4 mb-4">
                  <div className="flex items-center">
                    <div className="w-4 h-4 mr-2 bg-blue-500 rounded-full"></div>
                    <span className="text-sm">High Density</span>
                  </div>
                  <div className="flex items-center">
                    <div className="w-4 h-4 mr-2 bg-green-500 rounded-full"></div>
                    <span className="text-sm">Medium Density</span>
                  </div>
                  <div className="flex items-center">
                    <div className="w-4 h-4 mr-2 bg-yellow-500 rounded-full"></div>
                    <span className="text-sm">Low Density</span>
                  </div>
                  {userLocation && (
                    <div className="flex items-center">
                      <div className="w-4 h-4 mr-2 bg-blue-600 border-2 border-white rounded-full ring-2 ring-blue-600"></div>
                      <span className="text-sm">Your Location</span>
                    </div>
                  )}
                </div>

                {/* Map Container */}
                <div 
                  ref={mapRef} 
                  className="z-0 w-full rounded-lg h-96"
                  role="application"
                  aria-label="Interactive map showing visitor distribution"
                ></div>

                {/* Location Status */}
                <div className="mt-4 text-sm text-gray-600">
                  {userLocation ? (
                    <p className="flex items-center text-green-600">
                      <span className="mr-2">📍</span>
                      Using your location for personalized insights
                    </p>
                  ) : (
                    <p className="flex items-center text-gray-500">
                      <span className="mr-2">🔒</span>
                      Enable location services for personalized recommendations
                      {!locationAccess && (
                        <button 
                          onClick={() => {
                            if (navigator.geolocation) {
                              navigator.geolocation.getCurrentPosition(
                                (position) => {
                                  setUserLocation({
                                    lat: position.coords.latitude,
                                    lng: position.coords.longitude
                                  });
                                  setLocationAccess(true);
                                }
                              );
                            }
                          }}
                          className="ml-2 text-blue-600 underline hover:text-blue-800"
                        >
                          Try again
                        </button>
                      )}
                    </p>
                  )}
                </div>
              </div>
            )}

            {/* Real-time Tab */}
            {activeTab === "realtime" && (
              <div className="grid grid-cols-1 gap-6 lg:grid-cols-3">
                <div className="p-6 bg-white border border-gray-100 rounded-lg shadow lg:col-span-1">
                  <h3 className="mb-4 text-lg font-bold">Live Activity</h3>
                  {renderRealTimeVisitors()}
                </div>
                
                <div className="p-6 bg-white border border-gray-100 rounded-lg shadow lg:col-span-2">
                  <h3 className="mb-4 text-lg font-bold">Live Activity Map</h3>
                  <div className="relative bg-gray-100 rounded-lg h-96">
                    <div 
                      ref={mapRef} 
                      className="z-0 w-full rounded-lg h-96"
                    ></div>
                    <div className="absolute px-3 py-1 text-sm bg-white rounded-lg shadow top-2 right-2">
                      🔴 Live Updates Every 5s
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* Predictive Tab */}
            {activeTab === "predictive" && (
              <div className="space-y-6">
                {renderPredictiveInsights()}
              </div>
            )}

            {/* Feedback Tab */}
            {activeTab === "feedback" && (
              <div className="space-y-6">
                {renderFeedbackAnalytics()}
              </div>
            )}

            {/* Data Refresh Info */}
            <div className="flex items-center justify-between px-4 py-2 text-sm text-gray-500 bg-gray-100 rounded-lg">
              <span>
                {mode === "demo" ? (
                  <>📊 Showing demo data</>
                ) : (
                  <>🔴 Live data from Power BI</>
                )}
              </span>
              <span className="flex items-center">
                <span className="w-2 h-2 mr-2 bg-green-500 rounded-full animate-pulse"></span>
                Last updated: {new Date().toLocaleTimeString()}
                {activeTab === "realtime" && (
                  <span className="ml-2 text-xs text-blue-600">(Live)</span>
                )}
              </span>
            </div>
          </div>
        )}
        
        <ChatBot />
      </main>
    </div>
  );
};

export default Analytics;
